function GuideComponent:Initial(moduleId, specialGuide, receivedGuideRewards)
    self:InitRemoteGuideModule(moduleId)
    self:InitRemoteSpecialGuide(specialGuide)
   
    if tonumber(IsOpenGuide) == 0 then
        return
    end
    self:InitReceivedGuideRewards(receivedGuideRewards)

    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    self.playerDojo = playerComponent.playerDojo
    --self:InitModuleConf()
    self:InitWaitExecuteModule()

    if self.isInit then
        self.isInit = nil
        self:SetIsModuleReset(false)
        if self.waitModuleCount > 0 then 
            --- 初始化监听
            self:InitListener()
            self:StartCheckGuide()
        end 

    end
end

