    local t = {}
    for _, v in pairs(specialGuide) do
        t[tostring(v)] = v
    end
    self.completeSpecialGuide = t
end

function GuideComponent:InitReceivedGuideRewards(receivedGuideRewards)
    local dataList = parse_strings(checkString(receivedGuideRewards), ",")

    local guideStepId2Res = {}
    for key, value in pairs(dataList) do
        if not string.isEmpty(value) then
            guideStepId2Res[value] = true
        end
    end
    self._guideStepId2Res = guideStepId2Res

end

