---InitOneModuleConfByModuleStep
---根据模块阶段ids 初始化 一个模块配置
---@param moduleSteps table {stepId, stepId, ....}
function GuideComponent:InitOneModuleConfByModuleStep(moduleSteps)
    local oneModuleConf = {}
    for i, stepId in ipairs(moduleSteps) do
        ---@type SystemGuideModuleStepVo
        local vo = self:GetStepVo(stepId)
        table.insert(oneModuleConf, vo)
    end
    return oneModuleConf
end

---InitWaitExecuteModule
---初始化等待执行的模块
function GuideComponent:InitWaitExecuteModule()
    local completeModuleId   = checkNumber(self.moduleId)
    local curModuleStepIndex = 1
    local waitModuleCount    = 0
    local waitExecuteModule  = {}

    -- local moduleStepIdGroup = self:InitModuleStepIdGroup()
    local specialGuideIdMap = {}
    local loopGuideIdMap    = {}
    local closePreSyncGuideIdMap = {}

    ---@type SystemGuideModuleVo[]
    local systemGuideModuleVo = CfUtils.GetCf(AutoIds.IdSetting1003, "SystemGuideModuleVo", true)
    for i, systemGuideModuleVo in pairs(systemGuideModuleVo) do
        local moduleId = systemGuideModuleVo.guideModuleId
        local specialGuide = checkInt(systemGuideModuleVo.specialGuide)
        local isMainGuide  = specialGuide == GuideType.Main
        if specialGuide == GuideType.Function then
            specialGuideIdMap[tostring(moduleId)] = moduleId
        end
        if specialGuide == GuideType.Loop then
            loopGuideIdMap[tostring(moduleId)] = moduleId
        end
        if checkInt(systemGuideModuleVo.isClosePreSync) == 1 then
            closePreSyncGuideIdMap[tostring(moduleId)] = moduleId
        end

        local isFinish
        if isMainGuide then
            isFinish = checkNumber(moduleId) <= completeModuleId
        else
            isFinish = self.completeSpecialGuide[tostring(moduleId)] ~= nil
        end

        local ids = CfUtils.GetIdGroupValue(AutoIds.IdSetting1002, moduleId, "ids")
        if not isFinish and ids ~= nil then
            local stepIds = parse_strings(ids)
            local stepId = stepIds[curModuleStepIndex]
            if stepId == nil then
                printError("guide---------------->>>> stepId 是 空的")
            end

            ---@type SystemGuideModuleStepVo
            local stepVo = self:GetStepVo(stepId)
            local isCompleteModule = self:CheckCompleteCondition(stepVo)
            if isCompleteModule then
                if checkNumber(moduleId) < 1000 then
                    self:InitRemoteGuideModule(checkNumber(moduleId))
                else
                    self.completeSpecialGuide[tostring(moduleId)] = moduleId
                end
                printInfo("guide---------------->>>> 该模块 %s 满足完成模块条件 跳过该引导 ", moduleId)
            else

                local trigger         = stepVo.trigger
                --- 检查模块配置
                local condition       = stepVo.condition
                local conditionGroups = self:GetConditionGroups(condition)
                local moduleSteps     = self:CheckModuleConfig(systemGuideModuleVo, conditionGroups)
                local exitStopRequestCheckStep
                local preSync = false
                if moduleSteps then
                    stepIds   = moduleSteps
                    stepId    = stepIds[curModuleStepIndex]
                    condition = stepVo.condition
                    --- 如果有断线重连配置的话初始化 提交同步
                    preSync   = checkNumber(stepVo.sync) > 0
                    stepVo    = self:GetStepVo(stepId)
                    trigger   = stepVo.trigger
                    exitStopRequestCheckStep = systemGuideModuleVo.exitStopRequestCheckStep
                end
                
                local endStepIndex = #stepIds
                local triggerType, triggerParams = SafeUnpack(parse_strings(trigger, "#"))
                waitExecuteModule[moduleId] = {
                    stepIds                  = stepIds,
                    curModuleStepIndex       = curModuleStepIndex,
                    startStepIndex           = curModuleStepIndex,
                    startTriggerType         = checkNumber(triggerType),
                    startTriggerParams       = checkNumber(triggerParams),
                    startConditionGroups     = self:GetConditionGroupList(conditionGroups),
                    endStepIndex             = endStepIndex,
                    exitStopRequestCheckStep = exitStopRequestCheckStep,
                    systemFunction           = stepVo.systemFunction,
                    preSync                  = preSync
                }
                waitModuleCount = waitModuleCount + 1

            end
        end

    end
    
    self.specialGuideIdMap      = specialGuideIdMap
    self.loopGuideIdMap         = loopGuideIdMap
    self.closePreSyncGuideIdMap = closePreSyncGuideIdMap
    self.waitModuleCount        = waitModuleCount
    self.waitExecuteModule      = waitExecuteModule
end

---CheckIsFinishWaitExecuteModule
---检查是否完成等待执行模块
---@param moduleId  number 模块id
---@param stepIndex number 阶段下标
function GuideComponent:CheckIsFinishWaitExecuteModule(moduleId, stepIndex)
    --- 循环类型引导不移除
    if self.loopGuideIdMap[tostring(moduleId)] then return end
    local module = self.waitExecuteModule[moduleId]
    if stepIndex >= module.endStepIndex then
        printInfo("guide---------------->>>> 移除 模块 %s", moduleId)
        self:RemoveWaitExecuteModuleById(moduleId)
    end
    
end

---RemoveWaitExecuteModuleById
---移除等待执行模块
---@param moduleId number 模块id
function GuideComponent:RemoveWaitExecuteModuleById(moduleId)
    self.waitExecuteModule[moduleId] = nil
end

function GuideComponent:InitListener()
    self.listenerConf = {
        [Constants.EventNames.EVENT_REQUEST_COMPLETE]                    = Bind(self, self.OnRequestComplete),
        [Constants.EventNames.UIBattlingBackToFightReady]                = Bind(self, self.OnBattlingBackToFightReady),
        [Constants.EventNames.EVENT_GUIDE_WAIT_ANIMATE_EXECUTE_COMPLETE] = Bind(self, self.OnWaitAnimateComplete),
        [UISystemGuideSkipModule]                                        = Bind(self, self.OnEventSkipModuleAction),
        ["CHANGE_DEVICE_ORIENTATION"]                                    = Bind(self, self.OnChangeDeviceOrientation)
    }
    for listenerKey, func in pairs(self.listenerConf) do
        Events.AddListener(listenerKey, func)
    end
end
function GuideComponent:RemoveListener()
    if self.listenerConf == nil then return end

    for listenerKey, func in pairs(self.listenerConf) do
        Events.RemoveListener(listenerKey, func)
    end
    self.listenerConf = nil
end

