function GuideComponent:StartCheckGuide()
    printInfo("guide---------------->>>>  开始 检查引导 等待执行模块个数 %s", self.waitModuleCount)
    
    self.guideCo = cs_coroutine.start(function()
        self:LoadGuidePrefab()
        xTry(function()
            while self.waitModuleCount > 0 do
                printInfo("guide---------------->>>>  开始检查引导")
                local triggerModuleId = self:CheckAllWaitExecuteModule(self:GetWaitExecuteModule())
                printInfo("guide---------------->>>>  触发的模块id %s", triggerModuleId)
                self:ClearConditionCache()
                Events.Broadcast(Constants.EventNames.EVENT_GUIDE_MODULE_START)
                self:SetCurTriggerModuleId(triggerModuleId)
                self:StartModuleCo(triggerModuleId)
                --self:ExecuteGuideModule(triggerModuleId)
                
            end

            self.guideCo = nil
        end, function()
            printError("%s %s", self:GetCurTriggerModuleId(), debug.traceback())
            self:StopGuideCo()
            self:UpdateBlockerOpenState(false)
        end)

    end)
end


function GuideComponent:StopGuideCo()
    if isNull(self.guideCo) then return end
    cs_coroutine.stop(self.guideCo)
    self.guideCo = nil
end

---StartModuleCo
---执行剩余的引导阶段
---@param triggerModuleId number 触发的模块id
function GuideComponent:StartModuleCo(triggerModuleId)
    self._moduleCo = cs_coroutine.start(function()
        self:ExecuteGuideModule(triggerModuleId)

        self._moduleCo = nil
    end)
    while not isNull(self._moduleCo) do
        yield_return()
    end
end
function GuideComponent:StopModuleCo()
    if not isNull(self._moduleCo) then
        cs_coroutine.stop(self._moduleCo)
        self._moduleCo = nil
    end
end

---ExecuteGuideModule
---执行引导模块
---@param triggerModuleId number 触发的模块id
function GuideComponent:ExecuteGuideModule(triggerModuleId)
    printInfo("guide---------------->>>>  引导开启 模块id = %s", triggerModuleId)

    ----- 1. 执行剩余阶段引导
    local moduleState, skipStepCount = self:ExecuteLeftStep(triggerModuleId)
    --
    ----- 2, 检查模块状态
    self:CheckModuleExecuteResult(moduleState, triggerModuleId, skipStepCount)
    
end

---ExecuteLeftStep
---执行剩余的引导阶段
---@param triggerModuleId number 触发的模块id
function GuideComponent:ExecuteLeftStep(triggerModuleId)
    
    printInfo("guide---------------->>>>  开始 执行剩余阶段引导")
    local waitExecuteModuleConf = self:GetWaitExecuteModuleById(triggerModuleId)
    local stepIds            = waitExecuteModuleConf.stepIds
    local oneModuleCount     = #stepIds
    local curModuleStepIndex = waitExecuteModuleConf.curModuleStepIndex
    self._loopModuleId2IsCanActive[checkNumber(triggerModuleId)] = nil
    while curModuleStepIndex <= oneModuleCount do
        local stepId = stepIds[curModuleStepIndex]
        ---@type SystemGuideModuleStepVo
        local oneModuleStepConf = self:GetStepVo(stepId)
        if DEBUG then
            Events.Broadcast(Constants.EventNames.EVENT_GUIDE_SHOW_DEBUG_STEP_ID, oneModuleStepConf.stepId)
        end

        printInfo("guide---------------->>>>  开始 执行阶段id = %s", oneModuleStepConf.mark)
        
        local startStepIndex        = waitExecuteModuleConf.startStepIndex
        --- 如果不是 起始阶段id  则 需要检查触发
        if curModuleStepIndex ~= startStepIndex then
            local guideModuleState, skipStepCount = self:CheckStepTrigger(oneModuleStepConf, waitExecuteModuleConf)
            if guideModuleState then
                return guideModuleState, skipStepCount
            end
        else
            Events.Broadcast(Constants.EventNames.EVENT_GUIDE_SHOW_GUIDE_LAYER)
            Events.Broadcast(UISystemGuideUpdateSkipBtnShowState, oneModuleStepConf.skip == 1)
            
            local isWaitAnimateComplete = checkNumber(oneModuleStepConf.isWaitAnimateComplete)
            self:CheckIsWaitAnimateComplete(isWaitAnimateComplete)
        end

        self:RequestStepRewards(triggerModuleId, stepId)

        if (not self.closePreSyncGuideIdMap[tostring(triggerModuleId)]) and (self.moduleId == triggerModuleId or self.specialGuideIdMap[tostring(triggerModuleId)] ~= nil) and
                (checkNumber(oneModuleStepConf.sync) > 0 or (curModuleStepIndex == startStepIndex and waitExecuteModuleConf.preSync)) then
            printInfo("guide---------------->>>>  特殊引导 提前同步")
            self:SynchronizeStep(triggerModuleId, stepId)
        end

        printInfo("guide---------------->>>>  重新检查UI状态")

        ---跳过中不检查
        self:CheckUI()

        ---要在执行action 之前 设置
        self:SetIsWaitExecuteNextStep(true)

        --- 检查触发下一步引导之前 有没有请求
        local requestPath = oneModuleStepConf.requestPath
        if not isEmpty(requestPath)then
            local isCheck = true
            if waitExecuteModuleConf.exitStopRequestCheckStep and next(waitExecuteModuleConf.exitStopRequestCheckStep)  then
                for i, v in ipairs(waitExecuteModuleConf.exitStopRequestCheckStep) do
                    if v == oneModuleStepConf.stepId then
                        isCheck = false
                        break
                    end
                end
            end
            if isCheck then
                self.requestPath = requestPath
            end
        end

        self:SetIsForcedTrigger(false)
        printInfo("guide---------------->>>>  开始 显示 对应 action = %s   eventInfo = %s", oneModuleStepConf.actionInfo, oneModuleStepConf.eventInfo)
        --- 显示动作
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_SHOW_ACTION, oneModuleStepConf)

        self:SetIsStartWait(true)
        --- 等待执行下一阶段
        while self:GetIsWaitExecuteNextStep() do
            yield_return()
        end
        
        self:SetIsStartWait(false)

        printInfo("guide---------------->>>>  开始 检查同步")
        local syncStepId = checkNumber(oneModuleStepConf.sync)
        --local stepId = oneModuleStepConf.stepId
        local isSync = syncStepId > 0
        if curModuleStepIndex < waitExecuteModuleConf.endStepIndex then
            if isSync then
                self:SynchronizeStep(triggerModuleId, stepId)
            else
                printInfo("guide---------------->>>>  同步阶段 模块id = %s, 阶段id = %s", 0, stepId)
                GameUtils.RecordGuideStep({ guideId = 0, guideStepId = stepId })
            end
        end

        --- 进入下一步骤
        curModuleStepIndex = curModuleStepIndex + 1
        waitExecuteModuleConf.curModuleStepIndex = curModuleStepIndex
    end
end

---CheckStepTrigger
---@param oneModuleStepConf SystemGuideModuleStepVo
---@return number
function GuideComponent:CheckStepTrigger(oneModuleStepConf, waitExecuteModuleConf)
    
    Events.Broadcast(UISystemGuideUpdateSkipBtnShowState, oneModuleStepConf.skip == 1)
    printInfo("guide---------------->>>>  重新检查触发条件")
    local trigger      = oneModuleStepConf.trigger
    local triggerGroup = parse_strings(trigger, "#")
    local triggerType, triggerParams = SafeUnpack(triggerGroup)
    triggerType, triggerParams = checkNumber(triggerType), checkNumber(triggerParams)

    printInfo("guide---------------->>>>  开始 重新检查触发条件 %s %s", triggerType, triggerParams)

    while not self:CheckTriggerType(triggerType, triggerParams) and not self:GetIsModuleReset() do
        yield_return()
    end

    Events.Broadcast(Constants.EventNames.EVENT_GUIDE_SHOW_GUIDE_LAYER)
    printInfo("guide---------------->>>>  开始 模块重置状态 %s", self:GetIsModuleReset())
    if self:GetIsModuleReset() then
        printInfo("guide---------------->>>>  开始 模块重置状态 %s", GuideModuleState.Reset)
        return GuideModuleState.Reset
    end

    local isWaitAnimateComplete = checkNumber(oneModuleStepConf.isWaitAnimateComplete)
    self:CheckIsWaitAnimateComplete(isWaitAnimateComplete)
    local triggerRes = self:CheckTriggerState(triggerType, false)
    if not triggerRes then
        -- local skipStepCount = waitExecuteModuleConf.endStepIndex - waitExecuteModuleConf.curModuleStepIndex
        printInfo("guide---------------->>>>  触发失败 界面变空 跳过改引导", waitExecuteModuleConf.curModuleStepIndex)
        return GuideModuleState.Quit
    end

    ---步骤的跳过有两种情况
    ---1. 直接使用已有的数据直接判断
    ---2. 依赖于接口返回数据判断
    local res, skipStepCount = self:CheckCompleteCondition(oneModuleStepConf)
    if res then
        printInfo("guide---------------->>>> 满足阶段完成条件", skipStepCount)
        return GuideModuleState.CompleteStep, skipStepCount
    end

    local condition = oneModuleStepConf.condition
    printInfo("guide---------------->>>>  开始 检查条件 = %s", condition)
    if not self:CheckCondition(condition) then
        return GuideModuleState.Quit
    end
end

---CheckModuleState
---检查模块状态
---@param moduleState Constants.GuideModuleState
---@param triggerModuleId number 触发的模块id
function GuideComponent:CheckModuleExecuteResult(moduleState, triggerModuleId, skipStepCount)
    
    local waitExecuteModuleConf = self:GetWaitExecuteModuleById(triggerModuleId)
    if waitExecuteModuleConf == nil then
        return
    end
    
    if moduleState == GuideModuleState.Quit then
        local stepId = waitExecuteModuleConf.stepIds[waitExecuteModuleConf.curModuleStepIndex]
        printInfo("guide---------------->>>>  执行剩余阶段引导失败 模块id = %s  阶段id = %s ", triggerModuleId, stepId)
        printInfo("guide---------------->>>>  执行剩余阶段引导失败  = %s", waitExecuteModuleConf.curModuleStepIndex)
        waitExecuteModuleConf.curModuleStepIndex = waitExecuteModuleConf.endStepIndex
        -- self:SetIsInGuiding(false)
        -- self:SetGuidePrefabActive(false)
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_STOP_GUIDE)
        self:CompleteGuide(waitExecuteModuleConf, triggerModuleId, stepId)
    elseif moduleState == GuideModuleState.Reset then
        printInfo("guide---------------->>>> 重置引导模块 模块id = %s", triggerModuleId)
        --- 1. 初始化 单个模块数据
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1003, "SystemGuideModuleVo", triggerModuleId)
        waitExecuteModuleConf.stepIds = vo.exitAdd1

        --- 2. 重置 startStepIndex curModuleStepIndex
        waitExecuteModuleConf.startStepIndex = 0
        waitExecuteModuleConf.curModuleStepIndex = 1
        waitExecuteModuleConf.endStepIndex = #waitExecuteModuleConf.stepIds
        -- waitExecuteModuleConf.end

        waitExecuteModuleConf.exitStopRequestCheckStep = vo.exitStopRequestCheckStep

        --- 3. 关闭 再模块重置状态
        self:SetIsModuleReset(false)

        --- 4. 重新重置模块状态
        moduleState, skipStepCount = self:ExecuteLeftStep(triggerModuleId)

        --- 5. 重新检查模块状态
        self:CheckModuleExecuteResult(moduleState, triggerModuleId, skipStepCount)
        
    elseif moduleState == GuideModuleState.CompleteStep then
        -- print("skipStepCount", skipStepCount)
        waitExecuteModuleConf.curModuleStepIndex = waitExecuteModuleConf.curModuleStepIndex + (skipStepCount > 0 and skipStepCount or 1)
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_STOP_GUIDE)
        if waitExecuteModuleConf.curModuleStepIndex >= waitExecuteModuleConf.endStepIndex then
            self:CompleteGuide(waitExecuteModuleConf, triggerModuleId)

        else
            self:ExecuteGuideModule(triggerModuleId)
    
        end
        ----- 1. 重新重置模块状态
        --moduleState = self:ExecuteLeftStep(triggerModuleId)
        --
        ----- 2. 重新检查模块状态
        --self:CheckModuleState(moduleState, triggerModuleId)

    else
        self:CompleteGuide(waitExecuteModuleConf, triggerModuleId)

    end
end

function GuideComponent:CompleteGuide(waitExecuteModuleConf, triggerModuleId)
    --------------------------------------------
    --- 引导显示相关
    local stepIds            = waitExecuteModuleConf.stepIds
    printInfo("guide---------------->>>>  解除引导")
    local stepId            = stepIds[#stepIds]
    --- 1. 检查是否能退出引导
    ---@type SystemGuideModuleStepVo
    local oneModuleStepConf = self:GetStepVo(stepId)
    local moduleQuitFlag    = oneModuleStepConf.moduleQuitFlag
    local isQuit            = moduleQuitFlag > 0

    if isQuit then
        printInfo("guide---------------->>>> 该模块 %s 满足退出条件 设置不在引导中状态 ", triggerModuleId)
        --- 2. 设置不在引导中状态
        self:SetIsInGuiding(false)
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_MODULE_END)
    else
        printInfo("guide---------------->>>> 该模块 %s 暂时无法退出 ", triggerModuleId)

    end

    --- 2. 隐藏引导预制件
    if isQuit then
        self:SetGuidePrefabActive(false)
    end

    --------------------------------------------
    --- 引导数据处理相关

    Events.Broadcast(UISystemGuideUpdateSkipBtnShowState, false)
    
    --- 3. 同步引导 (先远程)
    self:SynchronizeStep(triggerModuleId, stepId)

    --- 4. 检查是否完成等待执行模块
    local curModuleStepIndex = waitExecuteModuleConf.curModuleStepIndex
    local stepIndex          = math.min(curModuleStepIndex, #stepIds)
    printInfo("guide---------------->>>>  检查是否完成等待执行模块")
    self:CheckIsFinishWaitExecuteModule(triggerModuleId, stepIndex)

    --- 5. 完成该引导
    if not self.loopGuideIdMap[tostring(triggerModuleId)] then
        self.waitModuleCount = self.waitModuleCount - 1
        printInfo("guide---------------->>>>  引导结束", self.waitModuleCount)
    else
        waitExecuteModuleConf.curModuleStepIndex = waitExecuteModuleConf.startStepIndex
        printInfo("guide---------------->>>>  循环引导%s结束", triggerModuleId)

    end
end

function GuideComponent:StartShowSkipBtnCo(skip)
    if checkNumber(skip) == 0 then return end
    self.showSkipCo = cs_coroutine.start(function ()
        yield_return(ShowSkipModuleSeconds)
        Events.Broadcast(UISystemGuideUpdateSkipBtnShowState, true)
    end)

end
function GuideComponent:StopShowSkipBtnCo()
    if isNull(self.showSkipCo) then return end
    cs_coroutine.stop(self.showSkipCo)
    self.showSkipCo = nil

end

