---SynchronizeStep
---向服务端发送请求同步阶段
---@param moduleId number 引导模块id
---@param stepId   number 引导步骤id
function GuideComponent:SynchronizeStep(moduleId, stepId)
    --- 循环类型引导不同步
    if self.loopGuideIdMap[tostring(moduleId)] then return end
    if self:GetIsModuleReset() then return end

    ---@type Engine.Tools.PlayerPrefsUtility
    --local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
    --PlayerPrefsUtility.SetEncryptedInt("GuideComponent", moduleId)
    if self.moduleId == checkNumber(moduleId) or self.completeSpecialGuide[tostring(moduleId)] then
        return
    end
    printInfo("guide---------------->>>>  同步阶段 模块id = %s, 阶段id = %s", moduleId, stepId)

    self.temp = true
    GameUtils.Request(Interfaces.PlayerGuide, { guideId = moduleId, guideStepId = stepId},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    if checkNumber(moduleId) >= 1000 then
                        ---更新全局缓存数据
                        self.playerDojo:AddSpecialGuideId(checkNumber(moduleId))
                        self.completeSpecialGuide[tostring(moduleId)] = moduleId
                    else
                        ---更新全局缓存数据
                        self.playerDojo:GuideId(checkNumber(moduleId))
                        self.moduleId = checkNumber(moduleId)
                    end
                    self.temp = false
                end
            end, function(exception)
                printError(exception.Message)
            end)

    while self.temp do
        yield_return()
    end
end

---RequestStepRewards
---请求引导奖励
function GuideComponent:RequestStepRewards(moduleId, stepId)
    print("RequestStepRewards", table.toString(self._guideStepId2Res))
    if self._guideStepId2Res[stepId] then
        return
    end
    ---防止请求没收到 提前同步
    self._guideStepId2Res[stepId] = true
    
    ---@type SystemGuideModuleStepVo
    local vo      = self:GetStepVo(stepId)
    local rewards = vo:GetRewards()
    printInfo("guide---------------->>>>  开始 填充奖励")
    if next(rewards) then
        GoodsUtils.DrawRewards(rewards)
        GameUtils.Request(Interfaces.PlayerGuideRewards, { guideId = moduleId, guideStepId = stepId},
                function(request, response)
                end)
    end

end

