---CheckAllWaitExecuteModule
---检查所有等待执行的引导模块
---@param waitExecuteModule table
function GuideComponent:CheckAllWaitExecuteModule(waitExecuteModule)
    local triggerModuleId
    while true do
        local isTrigger = false
        local startTriggerType
        ---@param v table {startStepIndex, startTriggerType, startTriggerParams, endStepIndex, curModuleStepIndex}
        for moduleId, v in pairs(waitExecuteModule) do
            startTriggerType = v.startTriggerType
            if self:CheckConditionGroupList(v.startConditionGroups, true) and self:CheckTriggerType(startTriggerType, v.startTriggerParams) then
                triggerModuleId = moduleId
                isTrigger = true
                break
            end
        end
        if not isTrigger then
            yield_return()
        else
            --- 触发条件满足  设置再引导中
            self:SetIsInGuiding(true)
            self:SetGuidePrefabActive(true)
            self:CheckTriggerState(startTriggerType)
            -- self:SetIsForcedTrigger(false)
            break
        end
    end
    return triggerModuleId
end


