function GuideComponent:CheckIsWaitAnimateComplete(isWaitAnimateComplete)
    if isWaitAnimateComplete > 0 then
        printInfo("guide---------------->>>>  检查 事件控制的动画是否执行完成")
        self:SetIsWaitAnimateComplete(true)
        while self:GetIsWaitAnimateComplete() do
