function GuideComponent:CheckModuleBackCondition(actionParams)
    if self:CheckIsConfigCondition(actionParams) then
        return true
    end
    local isSatisfy = self:CheckConditionByGroup(actionParams, ":")
    if isSatisfy then return end

    printInfo("guide---------------->>>>  检查 模块返回状态")
    self:OnBattlingBackToFightReady()

end

--- CheckCurModuleIsCompleteStep
--- 检查当前模块是否完成指定阶段
---@param stepIndex any
function GuideComponent:CheckCurModuleIsCompleteStep(stepIndex)
    local waitExecuteModule     = self:GetWaitExecuteModule()
    local triggerModuleId       = self:GetCurTriggerModuleId()
    if triggerModuleId == nil then
        return
    end
    local waitExecuteModuleConf = waitExecuteModule[triggerModuleId]
    return waitExecuteModuleConf.curModuleStepIndex > stepIndex
end

