function GuideComponent:GetModuleNextStepConfig()
    local waitExecuteModule     = self:GetWaitExecuteModule()
    local moduleId              = self:GetCurTriggerModuleId()
    if waitExecuteModule == nil then return nil end
        
    local waitExecuteModuleConf = waitExecuteModule[moduleId]
    local nextIndex             = waitExecuteModuleConf.curModuleStepIndex + 1
    local endStepIndex          = waitExecuteModuleConf.endStepIndex
    if nextIndex > endStepIndex then
        return
    end
    local stepIds = waitExecuteModuleConf.stepIds
    local stepId  = stepIds[nextIndex]
    return self:GetStepVo(stepId)
    
end

