---OnRequestComplete
---请求完成
---@param errCode number 0 请求完成
---@param path string
function GuideComponent:OnRequestComplete(errCode, path, data)
    ---不在引导中 不处理
    -- if not self:IsInGuiding() then return end

    ---如果存在 requestPath 两头去除空格
    local requestPath = self.requestPath
    if requestPath then
        path = string.trim(path)
        requestPath = string.trim(requestPath)
    end
    
    ---@type GuideComponentConditionPartial
    local comp = self.partialComps[GuidePartialType.Condition]
    if not isNull(comp) then
        comp:CheckInterfaceData(errCode, path, data)
    end
    
    if errCode == 0 and requestPath and requestPath == path then
        self.requestPath = nil
    end
end

---OnBattlingBackToFightReady
---手动退出战斗
function GuideComponent:OnBattlingBackToFightReady()
    ---不在引导中不处理
    if not self:IsInGuiding() then return end
    local curTriggerModuleId = self:GetCurTriggerModuleId()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1003, "SystemGuideModuleVo", curTriggerModuleId)
    if next(vo.exitAdd1) then
        self:SetIsModuleReset(true)
    end
end

function GuideComponent:OnWaitAnimateComplete()
    self:SetIsWaitAnimateComplete(false)
end

function GuideComponent:OnChangeDeviceOrientation()
    ---不在引导中 不处理
    if not self:IsInGuiding() then return end
    ---不是等待下一执行步骤 不处理
    if not self:GetIsStartWait() then return end

    self:UpdateBlockerOpenState(true)

    local triggerModuleId       = self:GetCurTriggerModuleId()
    ---@type SystemGuideModuleStepVo
    local oneModuleStepConf     = self:GetOneModuleStepConf(triggerModuleId)
    Events.Broadcast(Constants.EventNames.EVENT_GUIDE_RELOAD_SHOW_ACTION, oneModuleStepConf)
end

function GuideComponent:OnEventSkipModuleAction()
    if IsOpenGuideStepTest then
        return
    end
    if not isNull(self.skipCo) then
        return 
    end
    self.skipCo = cs_coroutine.start(function()
        ---1. stop self._moduleCo
        
        ---2. 更新当前触发模块本地数据
        local waitExecuteModule     = self:GetWaitExecuteModule()
        local triggerModuleId       = self:GetCurTriggerModuleId()
        local waitExecuteModuleConf = waitExecuteModule[triggerModuleId]
        --local skippedStepIndex
        --if tonumber(IsOpenGuideSkipTest) == 1 then
        --    skippedStepIndex = waitExecuteModuleConf.curModuleStepIndex
        --end
        ---将当前模块阶段下标移动到最后
        waitExecuteModuleConf.curModuleStepIndex = waitExecuteModuleConf.endStepIndex
    
        --------------------------------------------
        --- 引导显示相关
    
        printInfo("guide---------------->>>>  解除引导")
        local stepIds           = waitExecuteModuleConf.stepIds
        local stepId            = stepIds[#stepIds]
        --- 1. 检查是否能退出引导
        ---@type SystemGuideModuleStepVo
        local oneModuleStepConf = self:GetStepVo(stepId)
        local moduleQuitFlag    = oneModuleStepConf.moduleQuitFlag
        local isQuit            = moduleQuitFlag > 0
        
        self:SetSkipBlockerCondition(false)
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_RESET_UI_SHOW_STATE)
        
        if isQuit then
            printInfo("guide---------------->>>> 该模块 %s 满足退出条件 设置不在引导中状态 ", triggerModuleId)
            --- 2. 设置不在引导中状态
            self:SetIsInGuiding(false)
            Events.Broadcast(Constants.EventNames.EVENT_GUIDE_MODULE_END)
        else
            printInfo("guide---------------->>>> 该模块 %s 暂时无法退出 ", triggerModuleId)
    
        end
    
        --- 2. 隐藏引导预制件
        if isQuit then
            self:SetGuidePrefabActive(false)
        end
    
        --------------------------------------------
        --- 引导数据处理相关

        --- 2. 检查是否完成等待执行模块
        local curModuleStepIndex = waitExecuteModuleConf.curModuleStepIndex
        local stepIndex          = math.min(curModuleStepIndex, #stepIds)
        printInfo("guide---------------->>>>  检查是否完成等待执行模块")
        self:CheckIsFinishWaitExecuteModule(triggerModuleId, stepIndex)

        --- 3. 完成该引导
        if not self.loopGuideIdMap[tostring(triggerModuleId)] then
            self.waitModuleCount = self.waitModuleCount - 1
            printInfo("guide---------------->>>>  引导结束")
        else
            waitExecuteModuleConf.curModuleStepIndex = waitExecuteModuleConf.startStepIndex
            printInfo("guide---------------->>>>  循环引导%s结束", triggerModuleId)

        end
    
        --- 同步引导 (先远程)
        self:SynchronizeStep(triggerModuleId, stepId)
        
        --- 停止该模块引导
        self:StopModuleCo()

        ---结束下一步引导等待
        self:SetIsWaitExecuteNextStep(false)
        self:SetIsStartWait(false)
        self:SetIsForcedTrigger(false)
        
        --if skippedStepIndex and skippedStepIndex < stepIndex then
        --    waitExecuteModuleConf.curModuleStepIndex = skippedStepIndex
        --
        --    local skipStepId = stepIds[skippedStepIndex]
        --    ---@type SystemGuideModuleStepVo
        --    local stepVo = CfUtils.GetCfVo(AutoIds.IdSetting1002, "SystemGuideModuleStepVo", skipStepId)
        --    local trigger   = stepVo.trigger
        --    local triggerType, triggerParams = SafeUnpack(parse_strings(trigger, "#"))
        --    local condition       = stepVo.condition
        --    local conditionGroups = self:GetConditionGroups(condition)
        --    waitExecuteModuleConf.startStepIndex           = curModuleStepIndex
        --    waitExecuteModuleConf.startTriggerType         = checkNumber(triggerType)
        --    waitExecuteModuleConf.startTriggerParams       = checkNumber(triggerParams)
        --    waitExecuteModuleConf.startConditionGroups     = self:GetConditionGroupList(conditionGroups)
        --
        --    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        --
        --else
        --    
        --
        --end
        self.skipCo = nil
    end)
end


